import pytest

SCRIPT = Path(__file__).resolve().parents[1] / "scripts" / "tau_operator_actions.py"
sys.path.insert(0, str(SCRIPT.parent))
SPEC = importlib.util.spec_from_file_location("tau_operator_actions", SCRIPT)
