def state(
    *,
    lifecycle: str = "model_turn_running",
    permitted: list[str] | None = None,
    journal_seq: int = 7,
) -> dict[str, Any]:
    return {
        "schema": "monitor_herdr.tau_workspace_state.v1",
        "run_id": "run-1",
        "goal_hash": "sha256:goal",
        "cards": [{
            "node_id": "backend",
            "label": "coder/backend",
            "goal_hash": "sha256:goal",
            "lifecycle": lifecycle,
            "terminal": lifecycle in actions.TERMINAL_LIFECYCLES,
            "journal_seq": journal_seq,
            "permitted_operator_actions": permitted if permitted is not None else [
                "cancel", "add_next_turn_instruction", "request_independent_review", "request_human_approval",
            ],
        }],
    }


def receipt_for(request: dict[str, Any], *, outcome: str = "applied", resulting_seq: int = 8) -> dict[str, Any]:
    body = {
        "schema": actions.RECEIPT_SCHEMA,
        "request": dict(request),
        "request_sha256": actions.canonical_sha256(request),
        "run_id": request["run_id"],
        "node_id": request["node_id"],
        "attempt": 1,
        "goal_hash": request["goal_hash"],
        "outcome": outcome,
        "journal_transition": {
            "observed_seq": request["observed_journal_seq"],
            "resulting_seq": resulting_seq,
            "resulting_head_sha256": "sha256:head",
            "journal_changed": resulting_seq > request["observed_journal_seq"],
        },
    }
    return {**body, "sha256": actions.canonical_sha256(body)}


def submitter_for(**kwargs: Any):
    def _submit(request: dict[str, Any], *, run: Any = None) -> dict[str, Any]:
        return receipt_for(request, **kwargs)
    return _submit


