# --- receipt validation ----------------------------------------------------


def test_applied_action_returns_journal_changed_proof() -> None:
    result = actions.submit_action(
        state=state(), node_id="backend", action="cancel",
        actor="human_operator", submitter=submitter_for(),
    )

    assert result["ok"] is True
    assert result["outcome"] == "applied"
    assert result["journal_changed"] is True
    assert result["deferred"] is False


def test_deferred_outcomes_are_reported_not_treated_as_failure() -> None:
    for outcome in ("unsupported", "queued_for_next_turn", "fork_required"):
        result = actions.submit_action(
            state=state(), node_id="backend", action="cancel",
            actor="human_operator", submitter=submitter_for(outcome=outcome),
        )

        assert result["ok"] is True
        assert result["deferred"] is True
        assert result["outcome"] == outcome


def test_forged_receipt_sha_is_refused() -> None:
    def forged(request: dict[str, Any], *, run: Any = None) -> dict[str, Any]:
        receipt = receipt_for(request)
        receipt["outcome"] = "applied"  # mutate after the hash was taken
        receipt["run_id"] = "run-1"
        receipt["attempt"] = 99
        return receipt

    with pytest.raises(actions.OperatorActionError) as exc:
        actions.submit_action(
            state=state(), node_id="backend", action="cancel", actor="human_operator", submitter=forged
        )

    assert exc.value.code == "operator_action_receipt_sha_mismatch"


def test_receipt_for_a_different_request_is_refused() -> None:
    def mismatched(request: dict[str, Any], *, run: Any = None) -> dict[str, Any]:
        other = {**request, "node_id": "frontend"}
        return receipt_for(other)

    with pytest.raises(actions.OperatorActionError) as exc:
        actions.submit_action(
            state=state(), node_id="backend", action="cancel", actor="human_operator", submitter=mismatched
        )

    assert exc.value.code in {
        "operator_action_receipt_request_mismatch",
        "operator_action_receipt_identity_mismatch",
    }


def test_receipt_with_wrong_observed_seq_is_refused() -> None:
    def stale(request: dict[str, Any], *, run: Any = None) -> dict[str, Any]:
        body = receipt_for(request)
        body["journal_transition"]["observed_seq"] = 999
        return {**body, "sha256": actions.canonical_sha256({k: v for k, v in body.items() if k != "sha256"})}

    with pytest.raises(actions.OperatorActionError) as exc:
        actions.submit_action(
            state=state(), node_id="backend", action="cancel", actor="human_operator", submitter=stale
        )

    assert exc.value.code == "operator_action_receipt_transition_stale"


