# --- #1221 proof 8: pane-side edits cannot manufacture an action receipt -----


def test_locally_edited_card_cannot_produce_a_valid_receipt() -> None:
    """Faking a card's journal_seq yields a request Tau refuses, not a receipt."""
    tampered = state(journal_seq=999)

    def tau_rejects_stale(request: dict[str, Any], *, run: Any = None) -> dict[str, Any]:
        # Mirrors tau's own optimistic-concurrency guard.
        if request["observed_journal_seq"] != 7:
            raise actions.OperatorActionError("operator_action_stale_journal_seq", "999!=7")
        return receipt_for(request)

    with pytest.raises(actions.OperatorActionError) as exc:
        actions.submit_action(
            state=tampered, node_id="backend", action="cancel",
            actor="human_operator", submitter=tau_rejects_stale,
        )

    assert exc.value.code == "operator_action_stale_journal_seq"


def test_a_receipt_never_originates_from_herdr_state() -> None:
    """Without a submitter reaching Tau there is no receipt and no success."""
    def no_tau(request: dict[str, Any], *, run: Any = None) -> dict[str, Any]:
        raise actions.OperatorActionError("tau_unavailable", "no tau")

    with pytest.raises(actions.OperatorActionError) as exc:
        actions.submit_action(
            state=state(), node_id="backend", action="cancel",
            actor="human_operator", submitter=no_tau,
        )

    assert exc.value.code == "tau_unavailable"
